required_columns = [
    "ticket_id", "title", "description", "type", "category", "status",
    "request_source", "urgency", "impact", "priority", "requester",
    "assigned_group", "asset_type", "environment", "error_message",
    "symptoms", "technician_notes", "root_cause", "solution", "opened_at",
    "solved_at",
]


def main() -> None:
    OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    incidents_df = pd.DataFrame(incidents, columns=required_columns)

    if incidents_df["ticket_id"].is_unique is not True:
        raise ValueError("Ticket IDs must be unique.")
    missing_columns = [column for column in required_columns if column not in incidents_df.columns]
    if missing_columns:
        raise ValueError(f"Missing required columns: {missing_columns}")

    incidents_df.to_csv(OUTPUT_PATH, index=False)

    print(f"Generated {len(incidents_df)} tickets.")
    print(f"Tickets per category:\n{incidents_df['category'].value_counts().sort_index()}")
    print(f"Output CSV: {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
